import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import PostCard from '../components/PostCard';

// ✅ YAHAN 5000 KARO
const API_URL = 'http://localhost:5000';

const Profile = () => {
  const { id } = useParams();
  const { user: currentUser, updateUser } = useAuth();
  const navigate = useNavigate();
  const [profileUser, setProfileUser] = useState(null);
  const [posts, setPosts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [isFollowing, setIsFollowing] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [editName, setEditName] = useState('');
  const [editBio, setEditBio] = useState('');

  console.log('🔍 Profile - Current User:', currentUser);
  console.log('🔍 Profile - URL id:', id);

  if (!currentUser) {
    navigate('/login');
    return null;
  }

  const userId = id || currentUser.id;
  console.log('🔍 Profile - Final userId:', userId);

  const isOwnProfile = userId === currentUser.id;
  console.log('🔍 Profile - isOwnProfile:', isOwnProfile);

  useEffect(() => {
    if (!userId) {
      navigate(`/profile/${currentUser.id}`);
      return;
    }
    fetchProfile();
  }, [userId]);

  const fetchProfile = async () => {
    if (!userId) return;
    
    setLoading(true);
    try {
      console.log('📡 Fetching profile for:', userId);
      const userRes = await axios.get(`${API_URL}/api/users/${userId}`);
      console.log('✅ Profile data:', userRes.data);
      
      setProfileUser(userRes.data);
      setEditName(userRes.data.name || '');
      setEditBio(userRes.data.bio || '');
      
      const postsRes = await axios.get(`${API_URL}/api/posts/user/${userId}`);
      setPosts(postsRes.data);
      
      if (currentUser) {
        setIsFollowing(userRes.data.followers?.includes(currentUser.id));
      }
    } catch (err) {
      console.error('❌ Error fetching profile:', err);
      if (err.response?.status === 404) {
        navigate('/');
      }
    }
    setLoading(false);
  };

  const handleFollow = async () => {
    try {
      await axios.put(`${API_URL}/api/users/follow/${userId}`);
      setIsFollowing(!isFollowing);
      setProfileUser(prev => ({
        ...prev,
        followers: isFollowing 
          ? prev.followers?.filter(uid => uid !== currentUser.id) || []
          : [...(prev.followers || []), currentUser.id]
      }));
    } catch (err) {
      console.error(err);
    }
  };

  const handleUpdateProfile = async () => {
    try {
      const res = await axios.put(`${API_URL}/api/users/profile`, {
        name: editName,
        bio: editBio
      });
      updateUser(res.data);
      setProfileUser(prev => ({ ...prev, name: res.data.name, bio: res.data.bio }));
      setIsEditing(false);
      alert('✅ Profile updated!');
    } catch (err) {
      alert('❌ Failed to update');
    }
  };

  if (loading) return <div className="loading">Loading...</div>;
  if (!profileUser) return <div className="loading">User not found</div>;

  return (
    <div className="profile-container">
      <div className="profile-cover">
        <div className="cover-image"></div>
      </div>

      <div className="profile-header">
        <div className="profile-avatar-wrapper">
          <img 
            src={profileUser.profilePicture || '/default-avatar.png'} 
            alt="Profile" 
            className="profile-avatar-large"
          />
        </div>
        
        <div className="profile-info">
          <h2>{profileUser.name || profileUser.username}</h2>
          <p>@{profileUser.username}</p>
          
          <div className="profile-stats">
            <span>📊 {profileUser.followers?.length || 0} Followers</span>
            <span>📊 {profileUser.following?.length || 0} Following</span>
            <span>📝 {posts.length} Posts</span>
          </div>

          <div className="profile-bio">
            {profileUser.bio ? (
              <p>{profileUser.bio}</p>
            ) : (
              <p style={{ color: '#999' }}>
                {isOwnProfile ? 'Click Edit Profile to add bio' : 'No bio yet'}
              </p>
            )}
          </div>

          {/* ✅ EDIT BUTTON */}
          <div className="profile-buttons" style={{ marginTop: '15px' }}>
            {isOwnProfile ? (
              <button 
                onClick={() => setIsEditing(!isEditing)}
                style={{
                  background: '#1877f2',
                  color: 'white',
                  border: 'none',
                  padding: '10px 30px',
                  borderRadius: '8px',
                  fontSize: '16px',
                  fontWeight: '600',
                  cursor: 'pointer'
                }}
              >
                {isEditing ? '❌ Cancel' : '✏️ Edit Profile'}
              </button>
            ) : (
              <button 
                onClick={handleFollow}
                style={{
                  background: isFollowing ? '#e4e6eb' : '#1877f2',
                  color: isFollowing ? '#1c1c1e' : 'white',
                  border: 'none',
                  padding: '10px 30px',
                  borderRadius: '8px',
                  fontSize: '16px',
                  fontWeight: '600',
                  cursor: 'pointer'
                }}
              >
                {isFollowing ? '✓ Following' : '+ Follow'}
              </button>
            )}
          </div>

          {/* ✅ EDIT FORM */}
          {isEditing && isOwnProfile && (
            <div style={{
              marginTop: '20px',
              padding: '20px',
              background: '#f0f2f5',
              borderRadius: '12px'
            }}>
              <div style={{ marginBottom: '15px' }}>
                <label style={{ display: 'block', fontWeight: '600', marginBottom: '5px' }}>Name</label>
                <input
                  type="text"
                  value={editName}
                  onChange={(e) => setEditName(e.target.value)}
                  placeholder="Your full name"
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '2px solid #ddd',
                    borderRadius: '8px',
                    fontSize: '15px'
                  }}
                />
              </div>
              <div style={{ marginBottom: '15px' }}>
                <label style={{ display: 'block', fontWeight: '600', marginBottom: '5px' }}>Bio</label>
                <textarea
                  value={editBio}
                  onChange={(e) => setEditBio(e.target.value)}
                  placeholder="Tell us about yourself..."
                  maxLength={200}
                  rows="3"
                  style={{
                    width: '100%',
                    padding: '10px',
                    border: '2px solid #ddd',
                    borderRadius: '8px',
                    fontSize: '15px',
                    fontFamily: 'inherit',
                    resize: 'vertical'
                  }}
                />
                <span style={{ fontSize: '12px', color: '#999', display: 'block', textAlign: 'right' }}>
                  {editBio.length}/200
                </span>
              </div>
              <div style={{ display: 'flex', gap: '10px' }}>
                <button 
                  onClick={() => setIsEditing(false)}
                  style={{
                    background: '#e4e6eb',
                    color: '#1c1c1e',
                    border: 'none',
                    padding: '8px 25px',
                    borderRadius: '8px',
                    fontWeight: '600',
                    cursor: 'pointer'
                  }}
                >
                  Cancel
                </button>
                <button 
                  onClick={handleUpdateProfile}
                  style={{
                    background: '#1877f2',
                    color: 'white',
                    border: 'none',
                    padding: '8px 25px',
                    borderRadius: '8px',
                    fontWeight: '600',
                    cursor: 'pointer'
                  }}
                >
                  💾 Save
                </button>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="profile-posts">
        <h3>📝 Posts</h3>
        {posts.length === 0 ? (
          <p style={{ textAlign: 'center', color: '#999', padding: '20px' }}>
            No posts yet
          </p>
        ) : (
          posts.map(post => (
            <PostCard 
              key={post._id} 
              post={post} 
              onUpdate={fetchProfile}
              onDelete={fetchProfile}
            />
          ))
        )}
      </div>
    </div>
  );
};

export default Profile;
